32	  const a = window.__app, T = a.THREE, m = a.boats.fleets().find((x) => x.mesh.name === f).mesh, M = new T.Matrix4(); m.updateWorldMatrix(true, false);
33	  m.getMatrixAt(i, M); M.premultiply(m.matrixWorld); const p = new T.Vector3().setFromMatrixPosition(M); return [p.x, p.y, p.z];
