40	try {
41	  await page.evaluate(() => document.querySelectorAll('body *').forEach((e) => { if (!e.matches('canvas') && !e.querySelector('canvas')) e.style.visibility = 'hidden'; }));
42	  await setNight(0);
43	
44	  /* ---------- fleetOnly ---------- */
45	  const fo = await page.evaluate(() => {
46	    const a = window.__app, legacy = [];
47	    a.scene.traverse((o) => { if (o.isInstancedMesh && o.geometry.type === 'BoxGeometry' && ['f4f1ea', '2f6f8f', 'c23b2a'].includes(o.material.color?.getHexString())) legacy.push(o.name || o.uuid); });
48	    const fleets = a.boats?.fleets() ?? [];
