4	/** Chụp mọi giá trị khí quyển mà thời tiết có thể đổi (số thật, so sánh tuyệt đối). */
5	export const snapAtmosphere = (page) => page.evaluate(() => {
6	  const { scene, renderer } = window.__app;
7	  let sun, hemi, water, sky, clouds;
8	  scene.traverse((o) => {
9	    if (o.isDirectionalLight && o.castShadow !== undefined && o.shadow && o.intensity >= 0 && !sun && o.shadow.camera.right === 470) sun = o;
10	    else if (o.isHemisphereLight) hemi = o;
11	    else if (o.isWater || o.material?.uniforms?.distortionScale) water = o;
12	    else if (o.material?.uniforms?.turbidity) sky = o;
13	    else if (o.isInstancedMesh && o.count === 26 && o.material?.isMeshBasicMaterial && o.material.transparent) clouds = o;
14	  });
15	  const wu = water.material.uniforms, su = sky.material.uniforms;
16	  return {
17	    fogDensity: scene.fog.density, fogColor: scene.fog.color.toArray(), sunI: sun.intensity, hemiI: hemi.intensity, hemiColor: hemi.color.toArray(),
18	    exposure: renderer.toneMappingExposure, turbidity: su.turbidity.value, rayleigh: su.rayleigh.value,
19	    waterColor: wu.waterColor.value.toArray(), distortion: wu.distortionScale.value, size: wu.size.value, waterY: water.position.y,
20	    cloudOpacity: clouds.material.opacity, cloudColor: clouds.material.color.toArray(), cloudRotY: clouds.rotation.y
21	  };
