1	import * as THREE from 'three';
2	import { CONFIG } from '../config';
3	import { scene } from '../core/renderer';
4	import { windFx, weatherFx, vanished, shared } from '../core/shared';
5	import { rand } from '../common/math';
6	import type { BoatTypeId } from '../config';
7	import { btCreateFleet, btSetInfo, btSetBoat, btHideBoat, btCommit, btFleets, type BoatFleet } from './boats/fleet';
8	import { btCrowdSlots, btCrowdTarget, btCrowdLevel, btCrowdShown, btInExclusion } from './boats/crowd';
9	import { _e, _q, type VehicleType } from '../common/traffic';
10	import { vhCreateFleet, vhSetInfo, vhSetVehicle, vhHide, vhCommit, vhFleets, type VehicleFleet } from '../common/vehicles/fleet';
11	import { vhMaterial } from '../common/vehicles/material';
12	import { deckY } from '../bridges/dragon/profile';
13	import { ttlRoadY } from '../bridges/tran-thi-ly/profile';
14	
15	/* ============================ Xe cộ & thuyền của khu phố quanh Cầu Rồng ============================ */
16	interface Path { axis: 'x' | 'z'; min: number; max: number; fixed: number; profile?: (x: number) => number; hidden?: boolean }
17	interface CityVehicle { path: Path; lane: number; dir: number; type: VehicleType; s: number; speed: number; color: number }
18	
19	export const PATHS: Record<'axis' | 'ttl' | 'bachDang' | 'tranHungDao', Path> = {
20	  axis: { axis: 'x', min: -1900, max: 1480, fixed: 0, profile: deckY },
21	  ttl: { axis: 'x', min: -1900, max: 1480, fixed: CONFIG.ttl.z, profile: ttlRoadY, hidden: false }, // 2 làn trong mỗi chiều của Cầu Trần Thị Lý
22	  bachDang: { axis: 'z', min: -2400, max: 2400, fixed: -299 },
23	  tranHungDao: { axis: 'z', min: -2200, max: 2400, fixed: 299 }
24	};
25	const vehicles: CityVehicle[] = [];
26	export let cityFleet: VehicleFleet;   // 1 InstancedMesh 'traffic-city' cho mọi xe khu phố
27	
28	export function buildTraffic() {
29	  const V = CONFIG.vehicles, colors = V.carColors;
30	  const addLane = (path: Path, lane: number, dir: number, count: number, speed: number, mix: { bike: number; bus: number }) => {
31	    const range = path.max - path.min;
32	    for (let k = 0; k < count; k++) {
33	      const r = rand(); const type: VehicleType = r < mix.bike ? 'bike' : r < mix.bike + mix.bus ? 'bus' : 'car';
34	      vehicles.push({ path, lane, dir, type, s: path.min + (k + rand() * 0.5) * range / count, speed,
35	        color: type === 'bike' ? V.bikeColors[k % V.bikeColors.length] : type === 'bus' ? V.palette.busBody : colors[Math.floor(rand() * colors.length)] });
36	    }
37	  };
38	  const lanes = [4.875, 8.625, 12.375];
39	  for (const dir of [1, -1]) {
40	    addLane(PATHS.axis, lanes[0], dir, 26, 15, { bike: 0.05, bus: 0.08 });
41	    addLane(PATHS.axis, lanes[1], dir, 30, 12.5, { bike: 0.3, bus: 0.06 });
42	    addLane(PATHS.axis, lanes[2], dir, 44, 9.5, { bike: 0.85, bus: 0 });
43	    for (const [p, n] of [[PATHS.bachDang, 26], [PATHS.tranHungDao, 22]] as [Path, number][]) {
44	      addLane(p, 3.5, dir, n, 11, { bike: 0.3, bus: 0.05 }); addLane(p, 7.5, dir, n + 10, 8.5, { bike: 0.8, bus: 0 });
45	    }
46	    addLane(PATHS.ttl, 4.625, dir, 22, 13, { bike: 0.2, bus: 0.05 }); addLane(PATHS.ttl, 8.375, dir, 30, 9, { bike: 0.8, bus: 0 });
47	  }
48	  cityFleet = vhCreateFleet(vehicles.length, scene, 'traffic-city');
49	  vehicles.forEach((v, i) => vhSetInfo(cityFleet, i, v.type, v.color));
50	}
51	const _p = new THREE.Vector3();
52	/* Không cấp phát mỗi khung (D-018). Đèn pha/hậu bật trong shader theo uNight (common/vehicles/material.ts) */
53	export function updateTraffic(dt: number) {
54	  for (let i = 0; i < vehicles.length; i++) {
55	    const v = vehicles[i], P = v.path, range = P.max - P.min;
56	    if (P.hidden) { vhHide(cityFleet, i); continue; } // làn tắt bằng nút bật/tắt
57	    v.s += v.dir * v.speed * dt;
58	    if (v.s > P.max) v.s -= range; if (v.s < P.min) v.s += range;
59	    if ((P === PATHS.axis || P === PATHS.ttl) && vanished(i, weatherFx.clear)) { vhHide(cityFleet, i); continue; }   // đóng cầu (bão): dọn dần xe trên Cầu Rồng, Trần Thị Lý
60	    let yaw: number, pitch = 0;
61	    if (P.axis === 'x') {
62	      const y = P.profile(v.s), slope = (P.profile(v.s + 1) - P.profile(v.s - 1)) / 2;
63	      _p.set(v.s, y + 0.02, P.fixed + v.dir * v.lane); yaw = v.dir > 0 ? 0 : Math.PI; pitch = Math.atan(slope * v.dir);
64	    } else {
65	      _p.set(P.fixed - v.dir * v.lane, CONFIG.roadY + 0.03, v.s); yaw = v.dir > 0 ? -Math.PI / 2 : Math.PI / 2;
66	    }
67	    _q.setFromEuler(_e.set(0, yaw, pitch, 'YZX'));
68	    vhSetVehicle(cityFleet, i, _p, _q);
69	  }
70	  vhCommit(cityFleet);
71	}
72	/* Cho test (__app.traffic) */
73	export const trafficTest = { fleets: () => vhFleets, city: () => vehicles, paths: PATHS, material: vhMaterial, types: CONFIG.vehicles.types };
74	
75	/* Vùng cấm thuyền quanh công trường dìm đốt hầm (Hầm vượt sông Hàn, z ≈ −1700): chỉ có hiệu lực khi on */
76	export const boatKeepOut = { on: false, z0: -1760, z1: -1640 };
77	
78	/* Thuyền du lịch dọc sông Hàn — một đội tàu (fleet) chung ở layer 0 (có phản chiếu): 7 tàu chạy + chỗ cho 15 tàu tụ tập ban đêm (Task 4) */
79	export interface RiverBoat { x: number; z: number; dir: number; speed: number; len: number; type: BoatTypeId }
80	const boats: RiverBoat[] = [];
81	let fleet: BoatFleet;
82	export const RIVER_CROWD_FIRST = 7;   // instance 7.. dành cho tàu tụ tập
83	export function buildBoats() {
84	  const lanesX = [-48, -22, 22, 48];
85	  for (let i = 0; i < 7; i++) {
86	    // giữ đúng 2 lời gọi rand() mỗi tàu, đúng thứ tự (speed rồi len) — bất biến chuỗi seed; r đổi sang khoảng dài của kiểu
87	    const speed = 3 + rand() * 2, r = rand(), type: BoatTypeId = i % 2 ? 'B' : 'A', [lo, hi] = CONFIG.boats.types[type].len;
88	    boats.push({ x: lanesX[i % 4], z: -2200 + i * 650, dir: lanesX[i % 4] > 0 ? 1 : -1, speed, len: lo + r * (hi - lo), type });
89	  }
90	  fleet = btCreateFleet(RIVER_CROWD_FIRST + crowd.length, ['A', 'B', 'C'], scene, 'boats-river');
91	  boats.forEach((b, i) => btSetInfo(fleet, i, { type: b.type, variant: i % 3, led: (i * 2) % CONFIG.boats.led.colors.length, name: i % CONFIG.boats.names.length }));
92	  crowd.forEach((c, k) => btSetInfo(fleet, RIVER_CROWD_FIRST + k, c));
93	}
94	/* Tàu tụ tập ban đêm quanh Cầu Rồng / Cầu sông Hàn (spec G5, G6): đậu, trôi tròn chậm, mũi lắc nhẹ; hiện so le theo mức đêm, về bến khi bão */
95	const crowd = btCrowdSlots(), crowdA: number[] = crowd.map(() => 0);
96	let crowdLevel = 0;
97	export function btStepCrowd(f: BoatFleet, first: number, t: number, dt: number) {
98	  const C = CONFIG.boats.crowd, w = (Math.PI * 2) / C.driftPeriod;
99	  crowdLevel = btCrowdLevel(crowdLevel, btCrowdTarget(shared.uNight.value, weatherFx.boatAway), dt);
100	  crowd.forEach((c, k) => {
101	    const on = btCrowdShown(k, crowdLevel); crowdA[k] = on ? 1 : 0;
102	    if (!on) { btHideBoat(f, first + k); return; }
103	    const ph = t * w + c.phase, i = first + k;
104	    bq.setFromEuler(_e.set(Math.sin(t * 0.7 + k) * 0.012 * windFx.boatRock, c.yaw + C.yawSwing * Math.sin(ph * 0.7), Math.sin(t * 0.9 + k * 2) * 0.018 * windFx.boatRock, 'YXZ'));
105	    btSetBoat(f, i, bBase.set(c.x + C.drift * Math.cos(ph), 0, c.z + C.drift * Math.sin(ph)), bq, c.len);
106	  });
107	}
108	const bq = new THREE.Quaternion(), bBase = new THREE.Vector3();
109	export function updateBoats(dt: number, t: number) {
110	  boats.forEach((b, i) => {
111	    b.z += b.dir * b.speed * dt * (1 - weatherFx.boatAway); if (b.z > 2500) b.z = -2500; if (b.z < -2500) b.z = 2500;   // bão: thuyền chậm dần rồi dừng
112	    if (boatKeepOut.on && b.z > boatKeepOut.z0 && b.z < boatKeepOut.z1) b.z = b.dir > 0 ? boatKeepOut.z0 : boatKeepOut.z1;
113	    if (vanished(i, weatherFx.boatAway)) { btHideBoat(fleet, i); return; }   // về bến: ẩn dần
114	    bq.setFromEuler(_e.set(Math.sin(t * 0.9 + i) * 0.015 * windFx.boatRock, b.dir > 0 ? 0 : Math.PI, Math.sin(t * 1.1 + i * 2) * 0.02 * windFx.boatRock, 'YXZ'));   // mũi theo hướng chạy; tròng trành tăng theo gió (mặc định ×1)
115	    btSetBoat(fleet, i, bBase.set(b.x, 0, b.z), bq, b.len);
116	  });
117	  btStepCrowd(fleet, RIVER_CROWD_FIRST, t, dt);
118	  btCommit(fleet);
119	}
120	/* Cho test (__app.boats) */
121	export const boatsTest = { fleets: () => btFleets, running: () => boats, types: CONFIG.boats.types, crowd, crowdFirst: RIVER_CROWD_FIRST, crowdAlpha: () => crowdA, inExclusion: btInExclusion, drift: CONFIG.boats.crowd.drift };
