6	/* =====================================================================
7	   VẬT LIỆU XE CỘ — một vật liệu cho mọi hệ xe (thay MAT.vehicle / glass / headLamp / tailLamp), theo mẫu đội tàu (D-026).
8	   - aPart (theo đỉnh) ≠ aType (theo instance) ⇒ thu đỉnh về gốc: tam giác suy biến, không rasterize ⇒ một InstancedMesh vẽ cả 3 loại xe.
9	   - aRole (theo đỉnh, xem Role): Paint → aPaint (màu thân theo xe), Accent → aAccent (áo người lái), Helmet → aAccent.brg (mũ), còn lại giữ màu đỉnh.
10	   - Đèn pha / đèn hậu: emissive trong shader, bật khi uNight ≥ lamp.nightOn; ban ngày đỉnh đèn mang màu headDay / tailDay. Không đèn thật, không texture.
11	   Bóng đổ dùng vhDepthMaterial cùng bản vá, nếu không lượt vẽ bóng sẽ vẽ chồng cả 3 loại.
12	   ===================================================================== */
13	const V = CONFIG.vehicles;
14	const f = (x: number) => x.toFixed(3);   // số → hằng GLSL
15	
16	const VS_HEAD = /* glsl */`
17	attribute float aPart;
18	attribute float aRole;
19	attribute float aType;
20	attribute vec3 aPaint;
21	attribute vec3 aAccent;
22	varying float vLamp;
23	`;
24	const VS_COLLAPSE = /* glsl */`#include <begin_vertex>
25	if ( abs( aPart - aType ) > 0.5 ) transformed = vec3( 0.0 );`;
26	const VS_COLOR = /* glsl */`#include <color_vertex>
27	if ( abs( aRole - ${f(Role.Paint)} ) < 0.5 ) vColor.rgb = aPaint;                 // thân xe theo màu của xe
28	else if ( abs( aRole - ${f(Role.Accent)} ) < 0.5 ) vColor.rgb = aAccent;           // áo người lái
29	else if ( abs( aRole - ${f(Role.Helmet)} ) < 0.5 ) vColor.rgb = aAccent.brg;       // mũ bảo hiểm: hoán vị kênh màu áo
30	vLamp = abs( aRole - ${f(Role.Head)} ) < 0.5 ? 1.0 : ( abs( aRole - ${f(Role.Tail)} ) < 0.5 ? 2.0 : 0.0 );   // 1 đèn pha, 2 đèn hậu, 0 khác`;
31	
32	const uniforms = {
33	  uNight: shared.uNight,
34	  uHead: { value: new THREE.Color().setRGB(...V.lamp.head) },   // màu tuyến tính > 1 (giữ đúng MAT.headLamp cũ)
35	  uTail: { value: new THREE.Color().setRGB(...V.lamp.tail) }    // màu tuyến tính > 1 (giữ đúng MAT.tailLamp cũ)
36	};
37	
38	export const vhMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: V.roughness, metalness: V.metalness });
39	vhMaterial.name = 'vehicleFleet';
40	vhMaterial.onBeforeCompile = (s) => {
41	  Object.assign(s.uniforms, uniforms);
42	  s.vertexShader = VS_HEAD + s.vertexShader.replace('#include <begin_vertex>', VS_COLLAPSE).replace('#include <color_vertex>', VS_COLOR);
43	  s.fragmentShader = /* glsl */`
44	uniform float uNight;
45	uniform vec3 uHead;
46	uniform vec3 uTail;
47	varying float vLamp;
48	` + s.fragmentShader.replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
49	// đèn bật theo ngưỡng đêm (như cũ: ẩn mesh đèn khi uNight ≤ ${V.lamp.nightOn}), không nhấp nháy
50	float lampOn = step( ${f(V.lamp.nightOn)}, uNight );
51	if ( vLamp > 0.5 && vLamp < 1.5 ) totalEmissiveRadiance += uHead * lampOn;   // đèn pha
52	else if ( vLamp > 1.5 ) totalEmissiveRadiance += uTail * lampOn;              // đèn hậu`);
53	  vhMaterial.userData.fs = s.fragmentShader;
54	  vhMaterial.userData.vs = s.vertexShader;
55	};
56	vhMaterial.customProgramCacheKey = () => 'vehicleFleet';
57	
58	export const vhDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking });
59	vhDepthMaterial.onBeforeCompile = (s) => {
60	  s.vertexShader = 'attribute float aPart;\nattribute float aType;\n' + s.vertexShader.replace('#include <begin_vertex>', VS_COLLAPSE);
61	  vhDepthMaterial.userData.vs = s.vertexShader;
62	};
63	vhDepthMaterial.customProgramCacheKey = () => 'vehicleDepth';
