1	import * as THREE from 'three';
2	import { CONFIG, type VehicleTypeId } from '../../config';
3	import { vhBuildFleetGeometry, VEHICLE_TYPES } from './shapes';
4	import { vhMaterial, vhDepthMaterial } from './material';
5	
6	/* =====================================================================
7	   ĐỘI XE (fleet) — một InstancedMesh cho mỗi hệ xe = 1 lệnh vẽ (thay 4 khối hộp thân / cabin / đèn pha / đèn hậu).
8	   Mọi fleet dùng chung các BufferAttribute + index của vhBuildFleetGeometry() (cùng buffer GPU); mỗi fleet chỉ thêm 3 thuộc tính instance:
9	   aType (chỉ số loại trong VEHICLE_TYPES), aPaint (màu thân, tuyến tính), aAccent (màu áo người lái, tuyến tính).
10	   ===================================================================== */
11	export interface VehicleFleet { mesh: THREE.InstancedMesh; type: THREE.InstancedBufferAttribute; paint: THREE.InstancedBufferAttribute; accent: THREE.InstancedBufferAttribute }
12	
13	export const vhFleets: VehicleFleet[] = [];   // để test (__app.traffic.fleets)
14	const HIDDEN = new THREE.Matrix4().makeScale(0, 0, 0);
15	const SHIRTS = CONFIG.vehicles.shirtColors;
16	
17	export function vhCreateFleet(capacity: number, parent: THREE.Object3D, name: string): VehicleFleet {
18	  const src = vhBuildFleetGeometry(), geo = new THREE.BufferGeometry();
19	  for (const k of Object.keys(src.attributes)) geo.setAttribute(k, src.getAttribute(k));   // dùng chung đối tượng thuộc tính (không sao chép)
20	  geo.setIndex(src.index); geo.boundingBox = src.boundingBox; geo.boundingSphere = src.boundingSphere;
21	  const type = new THREE.InstancedBufferAttribute(new Float32Array(capacity), 1), paint = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3), accent = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 3), 3);
22	  geo.setAttribute('aType', type); geo.setAttribute('aPaint', paint); geo.setAttribute('aAccent', accent);
23	  const mesh = new THREE.InstancedMesh(geo, vhMaterial, capacity);
24	  mesh.name = name; mesh.customDepthMaterial = vhDepthMaterial; mesh.frustumCulled = false; mesh.castShadow = true;
25	  mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
26	  for (let i = 0; i < capacity; i++) mesh.setMatrixAt(i, HIDDEN);   // mọi xe khởi đầu ẩn (scale 0) tới lần đặt đầu tiên
27	  parent.add(mesh);
28	  const f = { mesh, type, paint, accent }; vhFleets.push(f);
29	  return f;
30	}
31	const _c = new THREE.Color();
32	/* Gán loại + màu thân (hex) cho xe i; màu áo chọn theo chỉ số (không dùng rand) — chỉ gọi lúc dựng */
33	export function vhSetInfo(f: VehicleFleet, i: number, type: VehicleTypeId, paint: number) {
34	  f.type.setX(i, VEHICLE_TYPES.indexOf(type));
35	  _c.setHex(paint); f.paint.setXYZ(i, _c.r, _c.g, _c.b);
36	  _c.setHex(SHIRTS[(i * 7 + 3) % SHIRTS.length]); f.accent.setXYZ(i, _c.r, _c.g, _c.b);
37	  f.type.needsUpdate = f.paint.needsUpdate = f.accent.needsUpdate = true;
38	}
39	const _m = new THREE.Matrix4(), _one = new THREE.Vector3(1, 1, 1);
40	/* Đặt xe i: base = điểm mặt đường dưới tâm xe, q = hướng (mũi xe +X của hình học) + dốc; kích thước thật nên scale 1 */
41	export function vhSetVehicle(f: VehicleFleet, i: number, base: THREE.Vector3, q: THREE.Quaternion) {
42	  f.mesh.setMatrixAt(i, _m.compose(base, q, _one));
43	}
44	export function vhHide(f: VehicleFleet, i: number) { f.mesh.setMatrixAt(i, HIDDEN); }
45	export function vhCommit(f: VehicleFleet) { f.mesh.instanceMatrix.needsUpdate = true; }
